override suspend fun doWork(): Result {
    val doseLogId = inputData.getInt(ExactAlarmScheduler.EXTRA_DOSE_LOG_ID, -1)
    if (doseLogId == -1) return Result.failure()
    val title = inputData.getString(ExactAlarmScheduler.EXTRA_TITLE) ?: return Result.failure()
    val text = inputData.getString(ExactAlarmScheduler.EXTRA_TEXT) ?: return Result.failure()
    val profileId = inputData.getInt(ExactAlarmScheduler.EXTRA_PROFILE_ID, -1)
    val medicationId = inputData.getInt(ExactAlarmScheduler.EXTRA_MEDICATION_ID, -1)
    val defaultDoseAmount = inputData.getString(ExactAlarmScheduler.EXTRA_DEFAULT_DOSE_AMOUNT) ?: ""
    NotificationHelper.sendReminder(applicationContext, doseLogId, title, text, profileId, medicationId, defaultDoseAmount)
    return Result.success()
}
